/**
 * report.controller.js
 * ─────────────────────────────────────────────────────────────────────────────
 * All existing API endpoints preserved unchanged.
 * Only addition: passes req.user.fullName (or username) to toPdf() so the
 * "Generated By" field in the PDF header is populated correctly.
 * ─────────────────────────────────────────────────────────────────────────────
 */
const asyncHandler = require('../utils/asyncHandler');
const ApiResponse  = require('../utils/ApiResponse');
const reportService = require('../services/report.service');
const logService    = require('../services/log.service');

/** Resolves a display name from the authenticated user object. */
function resolveUserName(user) {
  return user?.fullName || user?.username || user?.email || 'System';
}

// ─── Daily ───────────────────────────────────────────────────────────────────
const daily = asyncHandler(async (req, res) => {
  const { date, format } = req.query;
  const report = await reportService.dailyReport(date);
  await logService.record({
    userId:      req.user.userId,
    action:      'GENERATE_REPORT',
    entityType:  'Report',
    description: `Daily report for ${date} (${format})`,
    req,
  });

  if (format === 'csv') {
    res.setHeader('Content-Type', 'text/csv');
    res.setHeader('Content-Disposition', `attachment; filename="daily-report-${date}.csv"`);
    return res.send(reportService.toCsv(report.visits));
  }
  if (format === 'pdf') {
    res.setHeader('Content-Type', 'application/pdf');
    res.setHeader('Content-Disposition', `attachment; filename="daily-report-${date}.pdf"`);
    return reportService.toPdf(
      `Daily Visitor Report — ${date}`,
      report.visits,
      res,
      resolveUserName(req.user)
    );
  }
  new ApiResponse(200, 'Daily report generated.', report).send(res);
});

// ─── Monthly ──────────────────────────────────────────────────────────────────
const monthly = asyncHandler(async (req, res) => {
  const { year, month, format } = req.query;
  const report = await reportService.monthlyReport(Number(year), Number(month));
  await logService.record({
    userId:      req.user.userId,
    action:      'GENERATE_REPORT',
    entityType:  'Report',
    description: `Monthly report for ${year}-${month} (${format})`,
    req,
  });

  if (format === 'csv') {
    res.setHeader('Content-Type', 'text/csv');
    res.setHeader('Content-Disposition', `attachment; filename="monthly-report-${year}-${month}.csv"`);
    return res.send(reportService.toCsv(report.visits));
  }
  if (format === 'pdf') {
    res.setHeader('Content-Type', 'application/pdf');
    res.setHeader('Content-Disposition', `attachment; filename="monthly-report-${year}-${month}.pdf"`);
    return reportService.toPdf(
      `Monthly Visitor Report — ${year}-${String(month).padStart(2, '0')}`,
      report.visits,
      res,
      resolveUserName(req.user)
    );
  }
  new ApiResponse(200, 'Monthly report generated.', report).send(res);
});

// ─── Current Visitors ────────────────────────────────────────────────────────
const currentVisitors = asyncHandler(async (req, res) => {
  const { format } = req.query;
  const rows = await reportService.currentVisitorsReport();

  if (format === 'csv') {
    res.setHeader('Content-Type', 'text/csv');
    res.setHeader('Content-Disposition', 'attachment; filename="current-visitors.csv"');
    return res.send(reportService.toCsv(rows));
  }
  if (format === 'pdf') {
    res.setHeader('Content-Type', 'application/pdf');
    res.setHeader('Content-Disposition', 'attachment; filename="current-visitors.pdf"');
    return reportService.toPdf(
      'Current Visitors Report',
      rows,
      res,
      resolveUserName(req.user)
    );
  }
  new ApiResponse(200, 'Current visitors report generated.', rows).send(res);
});

module.exports = { daily, monthly, currentVisitors };
